import React, { createContext } from "react";
import products from "./roducts";

// نفس الـContext زي الأول، بس دلوقتي بيوفر بيانات محلية
// بدل ما كان بيعمل axios.get("https://dummyjson.com/products")
const apivalue = createContext();

function AllData({ children }) {
  return (
    <apivalue.Provider value={products}>
      {children}
    </apivalue.Provider>
  );
}

export { AllData, apivalue };
